Translate the following GNU C++14 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <bits/stdc++.h>
#define LL long long
#define LOOP(i, l, r) for (int i = l; i <= r; i++)
using namespace std;
const int P = 998244353, MOD = 1e9 + 7, BASE = 1e6;
int mod_value(ll d) { return (d % P + P) % P; }
LL total, count, sum[7];
int answer;
vector<int> p[7];

void generate_sequences(int depth, LL value) {
    total++;
    p[depth].push_back(mod_value(total - value));
    if (depth < 6) LOOP(i, 0, 9) generate_sequences(depth + 1, value * 10 + i);
}

int compute(int id, int f) {
    int position = lower_bound(p[id].begin(), p[id].end(), P - f) - p[id].begin();
    return ((LL)f * p[id].size() + sum[id] - (LL)P * (p[id].size() - position)) % MOD;
}

void explore(int depth, LL v) {
    if (v > total) return;
    if (depth >= 1) {
        if (v * BASE > total / 10 && v * BASE + BASE - 1 <= total) {
            int t = 1;
            LOOP(i, 0, 6) (answer += compute(i, mod_value(count - v * t))) %= MOD, t *= 10;
            LOOP(i, 0, 6) count += p[i].size();
            return;
        }
        answer = (answer + mod_value(++count - v)) % MOD;
    }
    for (int i = (!depth); i <= 9; i++) explore(depth + 1, v * 10 + i);
}

int main() {
    LL n_input;
    scanf("%lld", &n_input);
    total = 0;
    generate_sequences(0, 0);
    LOOP(i, 0, 6) {
        sort(p[i].begin(), p[i].end());
        for (int j = 0; j < (int)p[i].size(); j++) sum[i] += p[i][j];
    }
    count = 0;
    explore(0, 0);
    printf("%d\n", answer);
    return 0;
}
</original_code>
